    # positions, accumulating from 0.0 in ascending (n, c, r, s)
    # order: mu = sum(x)/M, z = x - mu, v = sum(z*z)/M,
    # R = 1/sqrt(v+eps), h = z*R. A non-finite intermediate aborts
    # before a result tensor exists, so no state can change on failure.
    out_data = [0.0] * length
    centered = [0.0] * length
    scales = []
    for n in range(B):
        for c in range(C):
            base = (n * C + c) * M
            total = 0.0
            for i in range(M):
                total += x[base + i]
                if not math.isfinite(total):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
            mu = total / M
            if not math.isfinite(mu):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            var_sum = 0.0
            for i in range(M):
                z_i = x[base + i] - mu
                if not math.isfinite(z_i):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                centered[base + i] = z_i
                square = z_i * z_i
                if not math.isfinite(square):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                var_sum += square
                if not math.isfinite(var_sum):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
            var = var_sum / M
            if not math.isfinite(var):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            denom_sq = var + eps
