                    if not math.isfinite(correction):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    correction = correction * R
                    if not math.isfinite(correction):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    correction = correction * Q
                    if not math.isfinite(correction):
                        raise ValueError(
