    # before a result tensor exists, so no state can change on failure.
    out_data = [0.0] * length
    centered = [0.0] * length
    scales = []
    for n in range(B):
        for c in range(C):
            base = (n * C + c) * M
            total = 0.0
            for i in range(M):
                total += x[base + i]
                if not math.isfinite(total):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
            mu = total / M
            if not math.isfinite(mu):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            var_sum = 0.0
            for i in range(M):
                z_i = x[base + i] - mu
                if not math.isfinite(z_i):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                centered[base + i] = z_i
                square = z_i * z_i
                if not math.isfinite(square):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
